        imageSharpnessTool.InputImage = inputImage;

        imageSharpnessTool.SetRunParam("SharpnessMode", "SquaredGrad");

        imageSharpnessTool.Run();

        // 获取处理结果
        var Result = imageSharpnessTool.Result;

        return Result.Sharpness;

