    DsaIpolGroup iGroup = this.GetXYIpolGroup();

    // 开始插补
    iGroup.ipolBegin();

    // 设置为绝对坐标系 ，不设置绝对坐标系
    iGroup.ipolSetAbsMode(true, -1);

    iGroup.ipolTanVelocity(1);
    iGroup.ipolTanAcceleration(10);
    iGroup.ipolTanDeceleration(10);

