            blendPrmTemp.pathBlendingPrm.prm = Convert.ToDouble(3);                  // 1;           //prm表示过渡的半径值
            blendPrmTemp.pathBlendingPrm.reserve2[0] = Convert.ToDouble(0.98);        //越小越远离
